17	/**
18	 * @file uram_array.hpp
19	 * @brief This file provides implementation of uram array helper class.
20	 *
21	 * This file is part of XF Common Utils Library.
22	 */
23	
24	#ifndef XF_UTILS_HW_URAM_ARRAY_H
25	#define XF_UTILS_HW_URAM_ARRAY_H
26	
27	#include <ap_int.h>
28	
29	namespace xf {
30	namespace common {
31	namespace utils_hw {
32	
33	namespace details {
34	/// @brief the structure of compute available uram block numbers.
35	///
36	/// @tparam width width of one data.
37	/// @tparam depth size of one array.
38	/// @tparam B     condition of W <= 72.
39	template <int total, int one, bool B = (total <= 72)>
40	struct need_num {
41	   private:
42	    static const int elem_per_line = 72 / total;
43	
44	   public:
45	    static const int value_x = ((one + (elem_per_line * 4096) - 1) / (elem_per_line * 4096));
46	    static const int value_y = ((total + 71) / 72);
47	};
48	
49	template <int total, int one>
50	struct need_num<total, one, false> {
51	   public:
52	    static const int value_x = (one + 4095) / 4096;
53	    static const int value_y = (total + 71) / 72;
54	};
55	} // details
56	
57	/**
58	 * @class UramArray uram_array.hpp "xf_utils_hw/uram_array.hpp"
59	 *
60	 * @brief Helper class to create URAM array that can be updated every cycle
61	 * with forwarding regs.
62	 *
63	 * Forwarding regs keeps a history of address and values, and when acess to URAM
64	 * hits the "cache", read from URAM is skipped. This addresses the
65	 * Read-After-Write dependency across iterations. The depth of the cache,
66	 * specified with the ``_NCache`` variable, dependes on the latency of actual
67	 * write. It is suggested to be set after initial sythesis attempts.
68	 *
69	 * When element can be held in one URAM row (72-bit), this helper would try to
70	 * pack multiple elements to one row. If it is beyond 72-bits, multiple URAMs
71	 * will be used to ensure elements can be fetched in one cycle.
72	 *
73	 * To make the cache really functional, HLS needs to be instructed to ignore
74	 * inter-iteration dependencies on ``blocks`` of ``UramArray`` objects.
75	 * Please refer to the test of this module for an example.
76	 *
77	 * \rst
78	 * .. ATTENTION::
79	 *     This module requires HLS 2019.1 or above.
80	 * \endrst
81	 *
82	 * @tparam _WData  the width of every element.
83	 * @tparam _NData  the number of elements in the array.
84	 * @tparam _NCache the number of cache.
85	 */
86	template <int _WData, int _NData, int _NCache>
87	class UramArray {
88	   public:
89	    UramArray() {
90	#pragma HLS inline
91	#pragma HLS bind_storage variable = blocks type = RAM_2P impl = URAM
92	#pragma HLS array_partition variable = blocks complete dim = 1
93	#pragma HLS array_partition variable = blocks complete dim = 2
94	#pragma HLS array_partition variable = _index complete dim = 1
95	#pragma HLS array_partition variable = _state complete dim = 1
96	        initialize();
97	    }
98	
99	   private:
100	    void initialize() {
101	#ifndef __SYNTHESIS__
102	        for (int i = 0; i < _num_uram_x; i++) {
103	            for (int j = 0; j < _num_uram_y; j++) {
104	                blocks[i][j] = (ap_uint<72>*)malloc(sizeof(ap_uint<72>) * 4096);
105	            }
106	        }
107	#endif
108	        for (int i = 0; i < _NCache; i++) {
109	#pragma HLS unroll
110	            _index[i] = -1;
111	            _state[i] = 0;
112	        }
113	    }
114	
115	   public:
116	    ~UramArray() {
117	#ifndef __SYNTHESIS__
118	        for (int i = 0; i < _num_uram_x; i++) {
119	            for (int j = 0; j < _num_uram_y; j++) {
120	                free(blocks[i][j]);
121	            }
122	        }
123	#endif
124	    }
125	
126	    /// @brief  initialization for uram.
127	    /// @param  d value for initialization.
128	    /// @return number of block which had been initialize.
129	    int memSet(const ap_uint<_WData>& d);
130	
131	    /// @brief write to uram.
132	    /// @param index the index which you want to write.
133	    /// @param d     the value what you want to write.
134	    void write(int index, const ap_uint<_WData>& d);
135	
136	    /// @brief  read from uram.
137	    /// @param  index the index which you want to read.
138	    /// @return value you had read.
139	    ap_uint<_WData> read(int index);
140	
141	   private:
142	    /// number elements per line, used with _WData<=72. For example, when _WData =
143	    /// 16, _elem_per_line is 4.
144	    static const int _elem_per_line;
145	
146	    /// piece of block using one time.
147	    static const int _num_parallel_block;
148	
149	    /// index numbers of one block.
150	    static const int _elem_per_block;
151	
152	    /// the numbers of need to access.
153	    static const int _num_uram_block;
154	    static const int _num_uram_x;
155	    static const int _num_uram_y;
156	
157	    /// the cache for saving latest index.
158	    int _index[_NCache];
159	
160	    /// the cache for saving latest value.
161	    ap_uint<_WData> _state[_NCache];
162	
163	   public:
164	// XXX this has to be public, otherwise `depencency false` cannot be
165	// specified.
166	#ifndef __SYNTHESIS__
167	    ap_uint<72>* blocks[details::need_num<_WData, _NData>::value_x][details::need_num<_WData, _NData>::value_y];
168	#else
169	    ap_uint<72> blocks[details::need_num<_WData, _NData>::value_x][details::need_num<_WData, _NData>::value_y][4096];
170	#endif
171	};
172	
173	// Const member variables
174	
175	template <int _WData, int _NData, int _NCache>
176	const int UramArray<_WData, _NData, _NCache>::_elem_per_line = (72 / _WData);
177	
178	template <int _WData, int _NData, int _NCache>
179	const int UramArray<_WData, _NData, _NCache>::_elem_per_block = (_elem_per_line * 4096);
180	
181	template <int _WData, int _NData, int _NCache>
182	const int UramArray<_WData, _NData, _NCache>::_num_parallel_block = ((_WData + 71) / 72);
183	
184	template <int _WData, int _NData, int _NCache>
185	const int UramArray<_WData, _NData, _NCache>::_num_uram_block = (details::need_num<_WData, _NData>::value_x *
186	                                                                 details::need_num<_WData, _NData>::value_y);
187	
188	template <int _WData, int _NData, int _NCache>
189	const int UramArray<_WData, _NData, _NCache>::_num_uram_x = (details::need_num<_WData, _NData>::value_x);
190	
191	template <int _WData, int _NData, int _NCache>
192	const int UramArray<_WData, _NData, _NCache>::_num_uram_y = (details::need_num<_WData, _NData>::value_y);
193	
194	// Methods
195	template <int _WData, int _NData, int _NCache>
196	int UramArray<_WData, _NData, _NCache>::memSet(const ap_uint<_WData>& d) {
197	    if (_num_uram_block == 0) return 0;
198	
199	    ap_uint<72> t;
200	l_init_value:
201	    for (int i = 0; i < 4096; i++) {
202	#pragma HLS PIPELINE II = 1
203	        for (int nx = 0; nx < _num_uram_x; nx++) {
204	#pragma HLS unroll
205	            for (int ny = 0; ny < _num_uram_y; ny++) {
206	#pragma HLS unroll
207	                if (_WData <= 72) {
208	                    for (int j = 0; j < _elem_per_line; j++) {
209	#pragma HLS unroll
210	                        t(j * _WData + _WData - 1, j * _WData) = d(_WData - 1, 0);
211	                    }
212	                    blocks[nx][ny][i] = t;
213	                } else {
214	                    int begin = ny * 72;
215	                    if (ny == (_num_parallel_block - 1))
216	                        blocks[nx][ny][i] = d(_WData - 1, begin);
217	                    else
218	                        blocks[nx][ny][i] = d(begin + 71, begin);
219	                }
220	            }
221	        }
222	    }
223	
224	// update d for cache
225	init_cache:
226	    for (int i = 0; i < _NCache; i++) {
227	#pragma HLS unroll
228	        _state[i] = d;
229	        _index[i] = 0;
230	    }
231	
232	    return _num_uram_block;
233	}
234	
235	template <int _WData, int _NData, int _NCache>
236	void UramArray<_WData, _NData, _NCache>::write(int index, const ap_uint<_WData>& d) {
237	#pragma HLS inline
238	    int div_block = 0, div_index = 0;
239	    int dec_block = 0, dec, begin;
240	
241	Write_Inner:
242	    for (int i = 0; i < _num_parallel_block; i++) {
243	        if (_WData <= 72) {
244	            div_block = index / _elem_per_block;
245	            dec_block = index % _elem_per_block;
246	            div_index = dec_block / _elem_per_line;
247	            dec = dec_block % _elem_per_line;
248	            begin = dec * _WData;
249	            ap_uint<72> tmp = blocks[div_block][0][div_index];
250	            tmp.range(begin + _WData - 1, begin) = d;
251	            blocks[div_block][0][div_index] = tmp;
252	        } else {
253	            div_block = index / 4096;
254	            dec_block = index % 4096;
255	            begin = i * 72;
256	            if (i == (_num_parallel_block - 1))
257	                blocks[div_block][i][dec_block] = d.range(_WData - 1, begin);
258	            else
259	                blocks[div_block][i][dec_block] = d.range(begin + 71, begin);
260	        }
261	    }
262	
263	Write_Cache:
264	    for (int i = _NCache - 1; i >= 1; i--) {
265	        _state[i] = _state[i - 1];
266	        _index[i] = _index[i - 1];
267	    }
268	    _state[0] = d;
269	    _index[0] = index;
270	}
271	
272	template <int _WData, int _NData, int _NCache>
273	ap_uint<_WData> UramArray<_WData, _NData, _NCache>::read(int index) {
274	#pragma HLS inline
275	    ap_uint<_WData> value;
276	    int div_block = 0, div_index = 0;
277	    int dec_block = 0, dec, begin;
278	
279	Read_Cache:
280	    for (int i = 0; i < _NCache; i++) {
281	        if (index == _index[i]) {
282	            value = _state[i];
283	            return value;
284	        }
285	    }
286	
287	Read_Inner:
288	    for (int i = 0; i < _num_parallel_block; i++) {
289	        if (_WData <= 72) {
290	            div_block = index / _elem_per_block;
291	            dec_block = index % _elem_per_block;
292	            div_index = dec_block / _elem_per_line;
293	            dec = dec_block % _elem_per_line;
294	            begin = dec * _WData;
295	            ap_uint<72> tmp = blocks[div_block][0][div_index];
296	            value = tmp.range(begin + _WData - 1, begin);
297	        } else {
298	            div_block = index / 4096;
299	            dec_block = index % 4096;
300	            begin = i * 72;
301	
302	            if (i == (_num_parallel_block - 1))
303	                value.range(_WData - 1, begin) = blocks[div_block][i][dec_block];
304	            else {
305	                value.range(begin + 71, begin) = blocks[div_block][i][dec_block];
306	            }
307	        }
308	    }
309	    return value;
310	}
311	
312	} // utils_hw
313	} // common
314	} // xf
315	
316	#endif
