27	/**
28	 * @brief cache is a URAM design for caching Read-only DDR/HBM memory spaces
29	 *
30	 * This function stores history data recently loaded from DDR/HBM in the on-chip memory(URAM).
31	 * It aims to reduce DDR/HBM access when the memory is accessed randomly.
32	 *
33	 * @tparam T 			    The type of the actual data accessed. Float and double is not supported.
34	 * @tparam ramRow			The number of rows each on chip ram has
35	 * @tparam groupramPart		The number of on chip ram used in cache
36	 * @tparam dataOneLine		The number of actual data each 512 can contain
37	 * @tparam addrWidth		The width of the address to access the memory
38	 * @tparam validRamType     The ram type of the valid flag array. 0 for LUTRAM, 1 for BRAM, 2 for URAM
39	 * @tparam addrRamType      The ram type of the onchip addr array. 0 for LUTRAM, 1 for BRAM, 2 for URAM
40	 * @tparam dataRamType      The ram type of the onchip data array. 0 for LUTRAM, 1 for BRAM, 2 for URAM
41	 */
42	
43	template <typename T,
44	          int ramRow,
45	          int groupRamPart,
46	          int dataOneLine,
47	          int addrWidth,
48	          int validRamType,
49	          int addrRamType,
50	          int dataRamType>
51	class cache {
52	   public:
53	    cache() {
54	#pragma HLS inline
55	#pragma HLS array_partition variable = valid block factor = 1 dim = 2
56	#pragma HLS array_partition variable = onChipRam1 block factor = 1 dim = 2
57	#pragma HLS array_partition variable = onChipRam0 block factor = 1 dim = 2
58	#pragma HLS array_partition variable = onChipAddr block factor = 1 dim = 2
59	
60	        if (validRamType == 0) {
61	#pragma HLS bind_storage variable = valid type = RAM_S2P impl = LUTRAM
62	        } else if (validRamType == 2) {
63	#pragma HLS bind_storage variable = valid type = RAM_S2P impl = BRAM
64	        } else {
65	#pragma HLS bind_storage variable = valid type = RAM_S2P impl = URAM
66	        }
67	
68	        if (addrRamType == 0) {
69	#pragma HLS bind_storage variable = onChipAddr type = RAM_S2P impl = LUTRAM
70	        } else if (addrRamType == 2) {
71	#pragma HLS bind_storage variable = onChipAddr type = RAM_S2P impl = BRAM
72	        } else {
73	#pragma HLS bind_storage variable = onChipAddr type = RAM_S2P impl = URAM
74	        }
75	
76	        if (dataRamType == 0) {
77	#pragma HLS bind_storage variable = onChipRam0 type = RAM_S2P impl = LUTRAM
78	#pragma HLS bind_storage variable = onChipRam1 type = RAM_S2P impl = LUTRAM
79	        } else if (dataRamType == 2) {
80	#pragma HLS bind_storage variable = onChipRam0 type = RAM_S2P impl = BRAM
81	#pragma HLS bind_storage variable = onChipRam1 type = RAM_S2P impl = BRAM
82	        } else {
83	#pragma HLS bind_storage variable = onChipRam0 type = RAM_S2P impl = URAM
84	#pragma HLS bind_storage variable = onChipRam1 type = RAM_S2P impl = URAM
85	        }
86	
87	#ifndef __SYNTHESIS__
88	        valid = new ap_uint<dataOneLine>*[ramRow];
89	        onChipRam1 = new ap_uint<512>*[ramRow];
90	        onChipRam0 = new ap_uint<512>*[ramRow];
91	        onChipAddr = new ap_uint<addrWidth>*[ramRow];
92	        for (int i = 0; i < ramRow; ++i) {
93	            valid[i] = new ap_uint<dataOneLine>[ groupRamPart ];
94	            onChipRam0[i] = new ap_uint<512>[ groupRamPart ];
95	            onChipRam1[i] = new ap_uint<512>[ groupRamPart ];
96	            onChipAddr[i] = new ap_uint<addrWidth>[ groupRamPart ];
97	        }
98	#endif
99	    }
100	
101	    ~cache() {
102	#ifndef __SYNTHESIS__
103	        for (int i = 0; i < ramRow; ++i) {
104	            delete[] valid[i];
105	            delete[] onChipRam0[i];
106	            delete[] onChipRam1[i];
107	            delete[] onChipAddr[i];
108	        }
109	        delete[] onChipAddr;
110	        delete[] onChipRam0;
111	        delete[] onChipRam1;
112	        delete[] valid;
113	#endif
114	    }
115	
116	    /// @brief  Initialization of the on chip memory when controlling single off chip memory.
117	    void initSingleOffChip() {
118	    Loop_init_uram:
119	        for (int j = 0; j < ramRow; ++j) {
120	#pragma HLS loop_tripcount min = 4096 avg = 4096 max = 4096
121	            for (int i = 0; i < groupRamPart; ++i) {
122	#pragma HLS loop_tripcount min = 8 avg = 8 max = 8
123	#pragma HLS pipeline II = 1
124	                valid[j][i] = 0;
125	                onChipAddr[j][i] = 0;
126	                onChipRam0[j][i] = 0;
127	            }
128	        }
129	    }
130	
131	    /// @brief  Initialization of the on chip memory when controlling dual off chip memory.
132	    void initDualOffChip() {
133	    Loop_init_uram:
134	        for (int j = 0; j < ramRow; ++j) {
135	#pragma HLS loop_tripcount min = 4096 avg = 4096 max = 4096
136	            for (int i = 0; i < groupRamPart; ++i) {
137	#pragma HLS loop_tripcount min = 8 avg = 8 max = 8
138	#pragma HLS pipeline II = 1
139	                valid[j][i] = 0;
140	                onChipAddr[j][i] = 0;
141	                onChipRam0[j][i] = 0;
142	                onChipRam1[j][i] = 0;
143	            }
144	        }
145	    }
