147	    /// @brief readOnly function with end flags.
148	    /// @param ddrMem 		The pointer for the off chip memory
149	    /// @param addrStrm		The read address should be sent from this stream
150	    /// @param e_addrStrm	The end flag for the addrStrm
151	    /// @param dataStrm		The data loaded from off chip memory
152	    /// @param e_dataStrm	The end flag for the dataStrm
153	    void readOnly(ap_uint<512>* ddrMem,
154	                  hls::stream<ap_uint<32> >& addrStrm,
155	                  hls::stream<bool>& e_addrStrm,
156	                  hls::stream<T>& dataStrm,
157	                  hls::stream<bool>& e_dataStrm) {
158	#pragma HLS inline off
159	
160	        ap_uint<dataOneLine> validCnt;
161	        for (int i = 0; i < dataOneLine; ++i) {
162	#pragma HLS loop_tripcount min = 8 avg = 8 max = 8
163	#pragma HLS pipeline II = 1
164	            validCnt[i] = 1;
165	        }
166	        const int size = sizeof(T) * 8;
167	
168	        ap_uint<addrWidth + 1> addrQue[4] = {-1, -1, -1, -1};
169	        ap_uint<512> pingQue[4] = {0, 0, 0, 0};
170	        ap_uint<dataOneLine> validQue[4] = {0, 0, 0, 0};
171	        int validAddrQue[4] = {-1, -1, -1, -1};
172	        int addrAddrQue[4] = {-1, -1, -1, -1};
173	        int ramAddrQue[4] = {-1, -1, -1, -1};
174	#pragma HLS array_partition variable = validQue complete dim = 1
175	#pragma HLS array_partition variable = validAddrQue complete dim = 1
176	#pragma HLS array_partition variable = ramAddrQue complete dim = 1
177	#pragma HLS array_partition variable = pingQue complete dim = 1
178	#pragma HLS array_partition variable = addrQue complete dim = 1
179	#pragma HLS array_partition variable = addrAddrQue complete dim = 1
180	
181	        bool e = e_addrStrm.read();
182	
183	        while (!e) {
184	#pragma HLS loop_tripcount min = 16500000 avg = 16500000 max = 16500000
185	#pragma HLS pipeline II = 1
186	#pragma HLS DEPENDENCE variable = valid type = inter direction = RAW distance = 1 true
187	#pragma HLS DEPENDENCE variable = onChipRam0 type = inter direction = RAW distance = 1 true
188	#pragma HLS DEPENDENCE variable = onChipAddr type = inter direction = RAW distance = 1 true
189	
190	            e = e_addrStrm.read();
191	            int index = addrStrm.read();
192	            int k00 = index % dataOneLine;
193	            int k01 = index / dataOneLine;
194	            int k10 = k01 % groupRamPart;
195	            int k11 = k01 / groupRamPart;
196	            int k20 = k11 % ramRow;
197	            int k21 = k11 / ramRow;
198	            int k30 = k21;
199	
200	            ap_uint<dataOneLine> validTmp;
201	            if (k01 == validAddrQue[0]) {
202	                validTmp = validQue[0];
203	            } else if (k01 == validAddrQue[1]) {
204	                validTmp = validQue[1];
205	            } else if (k01 == validAddrQue[2]) {
206	                validTmp = validQue[2];
207	            } else if (k01 == validAddrQue[3]) {
208	                validTmp = validQue[3];
209	            } else {
210	                validTmp = valid[k20][k10];
211	            }
212	            ap_uint<1> validBool = validTmp[k00]; // to check
213	            ap_uint<512> tmpV;
214	            ap_uint<addrWidth> address;
215	            ap_uint<addrWidth> addrTmp;
216	            if (k01 == addrAddrQue[0]) {
217	                addrTmp = addrQue[0];
218	            } else if (k01 == addrAddrQue[1]) {
219	                addrTmp = addrQue[1];
220	            } else if (k01 == addrAddrQue[2]) {
221	                addrTmp = addrQue[2];
222	            } else if (k01 == addrAddrQue[3]) {
223	                addrTmp = addrQue[3];
224	            } else {
225	                addrTmp = onChipAddr[k20][k10];
226	            }
227	            address = addrTmp;
228	            if ((validBool == 1) && (address == k30)) {
229	                if (k01 == ramAddrQue[0]) {
230	                    tmpV = pingQue[0];
231	                } else if (k01 == ramAddrQue[1]) {
232	                    tmpV = pingQue[1];
233	                } else if (k01 == ramAddrQue[2]) {
234	                    tmpV = pingQue[2];
235	                } else if (k01 == ramAddrQue[3]) {
236	                    tmpV = pingQue[3];
237	                } else {
238	                    tmpV = onChipRam0[k20][k10];
239	                }
240	            } else {
241	                tmpV = ddrMem[k01];
242	                onChipRam0[k20][k10] = tmpV;
243	                pingQue[3] = pingQue[2];
244	                pingQue[2] = pingQue[1];
245	                pingQue[1] = pingQue[0];
246	                pingQue[0] = tmpV;
247	                ramAddrQue[3] = ramAddrQue[2];
248	                ramAddrQue[2] = ramAddrQue[1];
249	                ramAddrQue[1] = ramAddrQue[0];
250	                ramAddrQue[0] = k01;
251	                ap_uint<addrWidth> tAddr = (ap_uint<addrWidth>)k30;
252	                addrTmp = tAddr;
253	                onChipAddr[k20][k10] = addrTmp;
254	                addrQue[3] = addrQue[2];
255	                addrQue[2] = addrQue[1];
256	                addrQue[1] = addrQue[0];
257	                addrQue[0] = addrTmp;
258	                addrAddrQue[3] = addrAddrQue[2];
259	                addrAddrQue[2] = addrAddrQue[1];
260	                addrAddrQue[1] = addrAddrQue[0];
261	                addrAddrQue[0] = k01;
262	            }
263	            if (validBool == 0) {
264	                validTmp = validCnt;
265	                valid[k20][k10] = validTmp;
266	                validQue[3] = validQue[2];
267	                validQue[2] = validQue[1];
268	                validQue[1] = validQue[0];
269	                validQue[0] = validTmp;
270	                validAddrQue[3] = validAddrQue[2];
271	                validAddrQue[2] = validAddrQue[1];
272	                validAddrQue[1] = validAddrQue[0];
273	                validAddrQue[0] = k01;
274	            }
275	            dataStrm.write(tmpV.range(size * (k00 + 1) - 1, size * k00));
276	            e_dataStrm.write(0);
277	        }
278	        e_dataStrm.write(1);
279	    }
