434	        int addrAddrQue[4] = {-1, -1, -1, -1};
435	        int ramAddrQue[4] = {-1, -1, -1, -1};
436	#pragma HLS array_partition variable = validQue complete dim = 1
437	#pragma HLS array_partition variable = validAddrQue complete dim = 1
438	#pragma HLS array_partition variable = cntQue complete dim = 1
439	#pragma HLS array_partition variable = ramAddrQue complete dim = 1
440	#pragma HLS array_partition variable = pingQue complete dim = 1
441	#pragma HLS array_partition variable = addrQue complete dim = 1
442	#pragma HLS array_partition variable = addrAddrQue complete dim = 1
443	
444	        for (int i = 0; i < cnt; ++i) {
445	#pragma HLS loop_tripcount min = 16500000 avg = 16500000 max = 16500000
446	#pragma HLS pipeline II = 1
447	#pragma HLS DEPENDENCE variable = valid type = inter direction = RAW distance = 1 true
448	#pragma HLS DEPENDENCE variable = onChipRam0 type = inter direction = RAW distance = 1 true
449	#pragma HLS DEPENDENCE variable = onChipRam1 type = inter direction = RAW distance = 1 true
