524	                onChipAddr[k20][k10] = addrTmp;
525	                addrQue[3] = addrQue[2];
526	                addrQue[2] = addrQue[1];
527	                addrQue[1] = addrQue[0];
528	                addrQue[0] = addrTmp;
529	                addrAddrQue[3] = addrAddrQue[2];
530	                addrAddrQue[2] = addrAddrQue[1];
531	                addrAddrQue[1] = addrAddrQue[0];
532	                addrAddrQue[0] = k01;
533	            }
534	            if (validBool == 0) {
535	                validTmp = validCnt;
536	                valid[k20][k10] = validTmp;
537	                validQue[3] = validQue[2];
538	                validQue[2] = validQue[1];
539	                validQue[1] = validQue[0];
540	                validQue[0] = validTmp;
541	                validAddrQue[3] = validAddrQue[2];
542	                validAddrQue[2] = validAddrQue[1];
543	                validAddrQue[1] = validAddrQue[0];
544	                validAddrQue[0] = k01;
545	            }
546	            data0Strm.write(tmpV.range(size * (k00 + 1) - 1, size * k00));
547	            data1Strm.write(tmpC.range(size * (k00 + 1) - 1, size * k00));
548	        }
549	    }
550	
551	    /// @brief readOnly function that index two off-chip buffers without end flags. Both of the buffers should be
552	    /// indexed in exactly the same behaviour.
553	    /// @param ddrMem0		The pointer for the first off chip memory
554	    /// @param ddrMem1		The pointer for the second off chip memory
555	    /// @param addrStrm		The read address should be sent from this stream
556	    /// @param e_addrStrm   The end flag for the addrStrm
557	    /// @param data0Strm	The data loaded from the first off chip memory
558	    /// @param e_data0Strm  The end flag for the data0Strm
559	    /// @param data1Strm	The data loaded from the second off chip memory
560	    /// @param e_data1Strm  The end flag for the data1Strm
561	    void readOnly(ap_uint<512>* ddrMem0,
562	                  ap_uint<512>* ddrMem1,
563	                  hls::stream<ap_uint<32> >& addrStrm,
564	                  hls::stream<bool>& e_addrStrm,
565	                  hls::stream<T>& data0Strm,
566	                  hls::stream<bool>& e_data0Strm,
567	                  hls::stream<T>& data1Strm,
568	                  hls::stream<bool>& e_data1Strm
569	
570	                  ) {
571	#pragma HLS inline off
572	
573	        ap_uint<dataOneLine> validCnt;
574	        for (int i = 0; i < dataOneLine; ++i) {
575	#pragma HLS loop_tripcount min = 8 avg = 8 max = 8
576	#pragma HLS pipeline II = 1
577	            validCnt[i] = 1;
578	        }
579	        const int size = sizeof(T) * 8;
580	
581	        ap_uint<addrWidth + 1> addrQue[4] = {-1, -1, -1, -1};
582	        ap_uint<512> pingQue[4] = {0, 0, 0, 0};
583	        ap_uint<512> cntQue[4] = {0, 0, 0, 0};
584	        ap_uint<dataOneLine> validQue[4] = {0, 0, 0, 0};
585	        int validAddrQue[4] = {-1, -1, -1, -1};
586	        int addrAddrQue[4] = {-1, -1, -1, -1};
587	        int ramAddrQue[4] = {-1, -1, -1, -1};
588	#pragma HLS array_partition variable = validQue complete dim = 1
589	#pragma HLS array_partition variable = validAddrQue complete dim = 1
590	#pragma HLS array_partition variable = cntQue complete dim = 1
591	#pragma HLS array_partition variable = ramAddrQue complete dim = 1
592	#pragma HLS array_partition variable = pingQue complete dim = 1
593	#pragma HLS array_partition variable = addrQue complete dim = 1
594	#pragma HLS array_partition variable = addrAddrQue complete dim = 1
595	
596	        bool e = e_addrStrm.read();
597	
598	        while (!e) {
599	#pragma HLS loop_tripcount min = 16500000 avg = 16500000 max = 16500000
600	#pragma HLS pipeline II = 1
601	#pragma HLS DEPENDENCE variable = valid type = inter direction = RAW distance = 1 true
602	#pragma HLS DEPENDENCE variable = onChipRam0 type = inter direction = RAW distance = 1 true
603	#pragma HLS DEPENDENCE variable = onChipRam1 type = inter direction = RAW distance = 1 true
604	#pragma HLS DEPENDENCE variable = onChipAddr type = inter direction = RAW distance = 1 true
605	            e = e_addrStrm.read();
606	
607	            int index = addrStrm.read();
608	            int k00 = index % dataOneLine;
609	            int k01 = index / dataOneLine;
610	            int k10 = k01 % groupRamPart;
611	            int k11 = k01 / groupRamPart;
612	            int k20 = k11 % ramRow;
613	            int k21 = k11 / ramRow;
614	            int k30 = k21;
615	
616	            ap_uint<dataOneLine> validTmp;
617	            if (k01 == validAddrQue[0]) {
618	                validTmp = validQue[0];
619	            } else if (k01 == validAddrQue[1]) {
620	                validTmp = validQue[1];
621	            } else if (k01 == validAddrQue[2]) {
622	                validTmp = validQue[2];
623	            } else if (k01 == validAddrQue[3]) {
624	                validTmp = validQue[3];
625	            } else {
626	                validTmp = valid[k20][k10];
627	            }
628	            ap_uint<1> validBool = validTmp[k00]; // to check
629	            ap_uint<512> tmpV, tmpC;
630	            ap_uint<addrWidth> address;
631	            ap_uint<addrWidth> addrTmp;
632	            if (k01 == addrAddrQue[0]) {
633	                addrTmp = addrQue[0];
634	            } else if (k01 == addrAddrQue[1]) {
635	                addrTmp = addrQue[1];
636	            } else if (k01 == addrAddrQue[2]) {
637	                addrTmp = addrQue[2];
638	            } else if (k01 == addrAddrQue[3]) {
639	                addrTmp = addrQue[3];
640	            } else {
641	                addrTmp = onChipAddr[k20][k10];
642	            }
643	            address = addrTmp;
644	            if ((validBool == 1) && (address == k30)) {
645	                if (k01 == ramAddrQue[0]) {
646	                    tmpV = pingQue[0];
647	                    tmpC = cntQue[0];
648	                } else if (k01 == ramAddrQue[1]) {
649	                    tmpV = pingQue[1];
650	                    tmpC = cntQue[1];
651	                } else if (k01 == ramAddrQue[2]) {
652	                    tmpV = pingQue[2];
653	                    tmpC = cntQue[2];
654	                } else if (k01 == ramAddrQue[3]) {
655	                    tmpV = pingQue[3];
656	                    tmpC = cntQue[3];
657	                } else {
658	                    tmpV = onChipRam0[k20][k10];
659	                    tmpC = onChipRam1[k20][k10];
660	                }
661	            } else {
662	                tmpV = ddrMem0[k01];
663	                tmpC = ddrMem1[k01];
664	                onChipRam0[k20][k10] = tmpV;
665	                onChipRam1[k20][k10] = tmpC;
666	                pingQue[3] = pingQue[2];
667	                pingQue[2] = pingQue[1];
668	                pingQue[1] = pingQue[0];
669	                pingQue[0] = tmpV;
670	                cntQue[3] = cntQue[2];
671	                cntQue[2] = cntQue[1];
672	                cntQue[1] = cntQue[0];
673	                cntQue[0] = tmpC;
674	                ramAddrQue[3] = ramAddrQue[2];
675	                ramAddrQue[2] = ramAddrQue[1];
676	                ramAddrQue[1] = ramAddrQue[0];
677	                ramAddrQue[0] = k01;
678	                ap_uint<addrWidth> tAddr = (ap_uint<addrWidth>)k30;
679	                addrTmp = tAddr;
680	                onChipAddr[k20][k10] = addrTmp;
681	                addrQue[3] = addrQue[2];
682	                addrQue[2] = addrQue[1];
683	                addrQue[1] = addrQue[0];
684	                addrQue[0] = addrTmp;
685	                addrAddrQue[3] = addrAddrQue[2];
686	                addrAddrQue[2] = addrAddrQue[1];
687	                addrAddrQue[1] = addrAddrQue[0];
688	                addrAddrQue[0] = k01;
689	            }
690	            if (validBool == 0) {
691	                validTmp = validCnt;
692	                valid[k20][k10] = validTmp;
693	                validQue[3] = validQue[2];
694	                validQue[2] = validQue[1];
695	                validQue[1] = validQue[0];
696	                validQue[0] = validTmp;
697	                validAddrQue[3] = validAddrQue[2];
698	                validAddrQue[2] = validAddrQue[1];
699	                validAddrQue[1] = validAddrQue[0];
700	                validAddrQue[0] = k01;
701	            }
702	            data0Strm.write(tmpV.range(size * (k00 + 1) - 1, size * k00));
703	            e_data0Strm.write(0);
704	            data1Strm.write(tmpC.range(size * (k00 + 1) - 1, size * k00));
705	            e_data1Strm.write(0);
706	        }
707	        e_data0Strm.write(1);
708	        e_data1Strm.write(1);
709	    }
710	
711	   private:
712	#ifndef __SYNTHESIS__
713	    ap_uint<dataOneLine>** valid;
714	    ap_uint<512>** onChipRam0;
715	    ap_uint<512>** onChipRam1;
716	    ap_uint<addrWidth>** onChipAddr;
717	#else
718	    ap_uint<dataOneLine> valid[ramRow][groupRamPart];
719	    ap_uint<512> onChipRam0[ramRow][groupRamPart];
720	    ap_uint<512> onChipRam1[ramRow][groupRamPart];
721	    ap_uint<addrWidth> onChipAddr[ramRow][groupRamPart];
722	#endif
723	
724	}; // cache class
725	
726	} // namespace utils_hw
727	} // namespace common
728	} // namespace xf
729	#endif //#ifndef XF_UTILS_HW_CACHE_H
